"""Check extraction facts and evidence, not supplier policy decisions."""

import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

from procurement.pdf_text import PdfDocument, PdfPage, read_pdf
from procurement.supplier_details import extract_supplier_details


PROJECT_ROOT = Path(__file__).resolve().parents[1]
SAMPLE_DIRECTORY = PROJECT_ROOT / "sample-data/engineer/task1-procurement"

# Hand-checked from the supplied PDFs; not generated by the parser under test.
EXPECTED_DETAILS = [
    ("Padma Textile Mills Ltd", "QT-2026-901", "2026-10-21", "101458013391", "000170141-0101"),
    ("Jamuna Trims and Accessories", "QT-2026-902", "2026-10-22", "102458023391", "000270241-0101"),
    ("Karnaphuli Yarn Traders", "QT-2026-903", "2026-10-23", "103458033391", "000370341-0101"),
    ("Surma Packaging Industries", "QT-2026-904", "2026-10-24", "104458043391", "000470441-0101"),
    ("Meghna Carton Works", "QT-2026-905", "2026-10-25", "105458053391", "000570541-0101"),
    ("Teesta Fabrics Ltd", "QT-2026-906", "2026-10-26", "106458063391", "000670641-0101"),
    ("Rupsha Zipper Factory", "QT-2026-907", "2026-10-20", "107458073391", "000770741-0101"),
    ("Bhairab Thread and Co", "QT-2026-908", "2026-10-21", None, None),
    ("Dhaleshwari Poly Pack", "QT-2026-909", "2026-10-22", "109458093391", "000970941-0101"),
    ("Kushiyara Box Industries", "QT-2026-910", "2026-10-23", "110458103391", "001071041-0101"),
]


def document_from_text(text: str, *, page_number: int = 1) -> PdfDocument:
    """Build a small parser fixture without creating extra supplier PDF data."""
    return PdfDocument(
        source_path=Path("parser-fixture.pdf"),
        pages=(PdfPage(page_number=page_number, text=text),),
        issues=(),
    )


class SupplierDetailsTests(unittest.TestCase):
    def test_all_ten_documents_match_hand_checked_details(self):
        for number, expected in enumerate(EXPECTED_DETAILS, start=1):
            with self.subTest(pack=number):
                document = read_pdf(SAMPLE_DIRECTORY / f"supplier-pack-{number:02d}.pdf")
                fields = extract_supplier_details(document)
                names = ("supplier_name", "quotation_number", "quotation_date", "tin", "bin")

                for name, value in zip(names, expected):
                    self.assertEqual(fields[name].value, value, name)
                    expected_status = "found" if value is not None else "not_found"
                    self.assertEqual(fields[name].status, expected_status, name)
                self.assertEqual(fields["purchase_request_reference"].value, "PR-2026-114")
                self.assertEqual(fields["purchase_request_reference"].status, "found")

    def test_evidence_is_exact_text_from_the_referenced_page(self):
        document = read_pdf(SAMPLE_DIRECTORY / "supplier-pack-01.pdf")
        fields = extract_supplier_details(document)

        for name, field in fields.items():
            self.assertTrue(field.evidence, name)
            for evidence in field.evidence:
                page = next(p for p in document.pages if p.page_number == evidence.page_number)
                self.assertIn(evidence.text, page.text, name)
                self.assertIn(field.value, evidence.text, name)

    def test_renaming_the_source_cannot_change_extracted_values(self):
        original = read_pdf(SAMPLE_DIRECTORY / "supplier-pack-01.pdf")
        renamed = PdfDocument(Path("unrelated-name.pdf"), original.pages, original.issues)

        self.assertEqual(extract_supplier_details(original), extract_supplier_details(renamed))

    def test_case_insensitive_labels_and_same_line_values(self):
        document = document_from_text(
            "Supplier name: Padma Textile Mills Ltd\n"
            "quotation NUMBER: QT-2026-901\nQuotation DATE: 2026-10-21\n"
            "Purchase request reference: PR-2026-114\n"
            "tin: 101458013391\nbin: 000170141-0101\n"
        )
        fields = extract_supplier_details(document)

        self.assertEqual(fields["supplier_name"].value, "Padma Textile Mills Ltd")
        self.assertEqual(fields["quotation_number"].value, "QT-2026-901")
        self.assertEqual(fields["quotation_date"].value, "2026-10-21")
        self.assertEqual(fields["purchase_request_reference"].value, "PR-2026-114")
        self.assertEqual(fields["tin"].value, "101458013391")
        self.assertEqual(fields["bin"].value, "000170141-0101")

    def test_page_numbers_come_from_the_source_not_a_new_counter(self):
        document = document_from_text("Quotation no.\nQT-2026-901\n", page_number=3)
        field = extract_supplier_details(document)["quotation_number"]

        self.assertEqual(field.value, "QT-2026-901")
        self.assertEqual(field.evidence[0].page_number, 3)

    def test_repeated_identical_values_keep_all_evidence(self):
        document = document_from_text("TIN: 101458013391\nTIN: 101458013391\n")
        field = extract_supplier_details(document)["tin"]

        self.assertEqual(field.status, "found")
        self.assertEqual(field.value, "101458013391")
        self.assertEqual(len(field.evidence), 2)

    def test_conflicting_values_are_not_resolved_by_taking_the_first(self):
        document = document_from_text("TIN: 101458013391\nTIN: 102458023391\n")
        field = extract_supplier_details(document)["tin"]

        self.assertEqual(field.status, "ambiguous")
        self.assertIsNone(field.value)
        self.assertEqual(len(field.evidence), 2)

    def test_conflicting_supplier_heading_and_signoff_are_ambiguous(self):
        document = document_from_text(
            "Padma Textile Mills Ltd\nQUOTATION\nFor Jamuna Trims and Accessories\n"
        )
        field = extract_supplier_details(document)["supplier_name"]

        self.assertEqual(field.status, "ambiguous")
        self.assertIsNone(field.value)

    def test_absent_registration_fields_do_not_get_invented_evidence(self):
        document = read_pdf(SAMPLE_DIRECTORY / "supplier-pack-08.pdf")
        fields = extract_supplier_details(document)

        for name in ("tin", "bin"):
            self.assertIsNone(fields[name].value)
            self.assertEqual(fields[name].status, "not_found")
            self.assertEqual(fields[name].evidence, ())

    def test_unsupported_or_empty_label_values_are_explicitly_unrecognized(self):
        for text in ("TIN: available on request\n", "TIN:", "Quotation no.\nDate\n"):
            with self.subTest(text=text):
                name = "quotation_number" if text.startswith("Quotation") else "tin"
                document = document_from_text(text)
                field = extract_supplier_details(document)[name]

                self.assertEqual(field.status, "unrecognized")
                self.assertIsNone(field.value)
                self.assertTrue(field.evidence)
                self.assertTrue(all(e.text in text for e in field.evidence))

    def test_unrecognized_occurrence_is_not_hidden_by_a_valid_occurrence(self):
        document = document_from_text("TIN: 101458013391\nTIN: pending\n")
        field = extract_supplier_details(document)["tin"]

        self.assertNotEqual(field.status, "found")
        self.assertIsNone(field.value)

    def test_impossible_and_unsupported_dates_are_not_guessed(self):
        for value in ("2026-02-30", "21/10/2026", "2026-99-99"):
            with self.subTest(value=value):
                field = extract_supplier_details(document_from_text(f"Date: {value}\n"))["quotation_date"]

                self.assertEqual(field.status, "unrecognized")
                self.assertIsNone(field.value)

    def test_unlabelled_date_and_pr_like_text_are_not_used_as_header_fields(self):
        document = document_from_text("Delivery by 2026-10-21. Mention PR-2026-114 when calling.\n")
        fields = extract_supplier_details(document)

        self.assertEqual(fields["quotation_date"].status, "not_found")
        self.assertEqual(fields["purchase_request_reference"].status, "not_found")

    def test_ordinary_tin_and_bin_words_are_not_registration_labels(self):
        document = document_from_text("Items include tin 123 and bin 456 units.\n")
        fields = extract_supplier_details(document)

        self.assertEqual(fields["tin"].status, "not_found")
        self.assertEqual(fields["bin"].status, "not_found")


class SupplierPreviewTests(unittest.TestCase):
    def test_preview_prints_values_and_page_evidence(self):
        result = subprocess.run(
            [sys.executable, "-m", "procurement.supplier_details", str(SAMPLE_DIRECTORY / "supplier-pack-01.pdf")],
            cwd=PROJECT_ROOT, capture_output=True, text=True,
        )

        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn("Padma Textile Mills Ltd", result.stdout)
        self.assertIn("QT-2026-901", result.stdout)
        self.assertIn("Page 1", result.stdout)

    def test_missing_registration_fields_make_preview_request_attention(self):
        result = subprocess.run(
            [sys.executable, "-m", "procurement.supplier_details", str(SAMPLE_DIRECTORY / "supplier-pack-08.pdf")],
            cwd=PROJECT_ROOT, capture_output=True, text=True,
        )

        self.assertNotEqual(result.returncode, 0)
        self.assertIn("tin: not_found", result.stdout)
        self.assertIn("bin: not_found", result.stdout)

    def test_reader_issue_is_not_lost_when_all_six_fields_are_found(self):
        import pymupdf

        with tempfile.TemporaryDirectory() as folder:
            path = Path(folder) / "with-blank-page.pdf"
            with pymupdf.open(SAMPLE_DIRECTORY / "supplier-pack-01.pdf") as source:
                source.new_page()
                source.save(path)
            result = subprocess.run(
                [sys.executable, "-m", "procurement.supplier_details", str(path)],
                cwd=PROJECT_ROOT, capture_output=True, text=True,
            )

        self.assertNotEqual(result.returncode, 0)
        self.assertIn("Page 2 has no selectable text", result.stdout)
        self.assertIn("QT-2026-901", result.stdout)


if __name__ == "__main__":
    unittest.main()
